    final entriesRepository = MockEntriesRepository();
    when(() => entriesRepository.cachedEntries).thenReturn(const []);
    final now = DateTime.now();
    when(() => entriesRepository.list(cursor: any(named: 'cursor'))).thenAnswer(
      (_) async => Right(
